import unittest
from retry_after import delay
class RetryAfterTests(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(delay('7'), 7)
        self.assertEqual(delay(' 12 '), 12)
    def test_negative(self):
        self.assertEqual(delay('-4'), 0)
    def test_invalid(self):
        self.assertIsNone(delay('later'))
        self.assertIsNone(delay('1.5'))

