import unittest
from datetime import datetime, timedelta, timezone
from clock import as_utc
class ClockTests(unittest.TestCase):
    def test_offset(self):
        local = datetime(2026, 1, 2, 12, 0, tzinfo=timezone(timedelta(hours=5, minutes=30)))
        self.assertEqual(as_utc(local), datetime(2026, 1, 2, 6, 30, tzinfo=timezone.utc))
    def test_naive(self):
        with self.assertRaises(ValueError):
            as_utc(datetime(2026, 1, 2, 12, 0))

import unittest
from lease import can_write
class LeaseTests(unittest.TestCase):
    def test_owner(self):
        self.assertTrue(can_write(8, 8, True))
    def test_stale(self):
        self.assertFalse(can_write(7, 8, True))
        self.assertFalse(can_write(8, 8, False))
